class MobileShell extends StatefulWidget{const MobileShell({super.key,required this.apiBaseUrl});final String apiBaseUrl;@override State<MobileShell> createState()=>_MobileShellState();}
class _MobileShellState extends State<MobileShell>{
 late final MarketRepository marketsRepo;late final MarketStatusRepository statusRepo;late final IndicatorRepository indicatorsRepo;late final HistoryRepository historyRepo;late final IchimokuHistoryRepository ichimokuRepo;late final NewsAlertRepository newsRepo;late final UserSyncRepository userSyncRepo;
 late Future<List<MarketRow>> markets;late Future<Map<String,MarketStatus>> statuses;int index=0;
 @override void initState(){super.initState();final api=ApiClient(baseUrl:widget.apiBaseUrl);marketsRepo=MarketRepository(api);statusRepo=MarketStatusRepository(api);indicatorsRepo=IndicatorRepository(api);historyRepo=HistoryRepository(api);ichimokuRepo=IchimokuHistoryRepository(api);newsRepo=NewsAlertRepository(api);userSyncRepo=UserSyncRepository(api);markets=marketsRepo.fetchScanner();statuses=statusRepo.fetchAll();}
 Future<void> refresh()async{final m=marketsRepo.fetchScanner(),s=statusRepo.fetchAll();setState((){markets=m;statuses=s;});await Future.wait([m,s]);}
 @override Widget build(BuildContext context){const titles=['Cockpit','Marchés','Favoris','Indicateurs','Signaux','News'];return Scaffold(appBar:AppBar(title:Text('Cockpit Marchés AI · ${titles[index]}'),actions:[IconButton(onPressed:refresh,icon:const Icon(Icons.refresh))]),body:FutureBuilder<List<MarketRow>>(future:markets,builder:(context,ms){if(ms.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(ms.hasError)return Center(child:Text('API indisponible : ${ms.error}'));final rows=ms.data??const<MarketRow>[];return FutureBuilder<Map<String,MarketStatus>>(future:statuses,builder:(context,ss){final statusMap=ss.data??const<String,MarketStatus>{};return switch(index){0=>CockpitView(rows:rows,onRefresh:refresh),1=>MarketsView(rows:rows,statuses:statusMap,onRefresh:refresh,historyRepo:historyRepo,indicatorRepo:indicatorsRepo,ichimokuRepo:ichimokuRepo),2=>WatchlistView(rows:rows,repository:userSyncRepo),3=>IndicatorsView(rows:rows,repository:indicatorsRepo),4=>SignalsView(rows:rows),_=>NewsAlertsView(repository:newsRepo,syncRepository:userSyncRepo,rows:rows)};});}),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.dashboard_outlined),label:'Cockpit'),NavigationDestination(icon:Icon(Icons.candlestick_chart_outlined),label:'Marchés'),NavigationDestination(icon:Icon(Icons.star_border),label:'Favoris'),NavigationDestination(icon:Icon(Icons.monitor_heart_outlined),label:'Indicateurs'),NavigationDestination(icon:Icon(Icons.bolt_outlined),label:'Signaux'),NavigationDestination(icon:Icon(Icons.notifications_outlined),label:'News')]));}
}

class CockpitView extends StatelessWidget{const CockpitView({super.key,required this.rows,required this.onRefresh});final List<MarketRow> rows;final Future<void>Function() onRefresh;@override Widget build(BuildContext context){final buy=rows.where((r)=>_tone(r.signal)=='buy').length,sell=rows.where((r)=>_tone(r.signal)=='sell').length;return RefreshIndicator(onRefresh:onRefresh,child:ListView(padding:const EdgeInsets.all(16),children:[Text('Vue d’ensemble',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),Wrap(spacing:10,runSpacing:10,children:[_Metric(label:'Actifs suivis',value:'${rows.length}'),_Metric(label:'Achats',value:'$buy'),_Metric(label:'Ventes',value:'$sell')]),const SizedBox(height:18),...rows.take(8).map((r)=>_MarketTile(row:r))]));}}

class MarketsView extends StatelessWidget{const MarketsView({super.key,required this.rows,required this.statuses,required this.onRefresh,required this.historyRepo,required this.indicatorRepo,required this.ichimokuRepo});final List<MarketRow> rows;final Map<String,MarketStatus> statuses;final Future<void>Function() onRefresh;final HistoryRepository historyRepo;final IndicatorRepository indicatorRepo;final IchimokuHistoryRepository ichimokuRepo;@override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:onRefresh,child:ListView.separated(padding:const EdgeInsets.all(16),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(context,i){final row=rows[i],status=statuses[row.key];return Card(child:ListTile(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AssetDetailScreen(row:row,status:status,historyRepo:historyRepo,indicatorRepo:indicatorRepo,ichimokuRepo:ichimokuRepo))),title:Text(row.symbol),subtitle:Text(status==null?'${row.name} · ${row.kind}':'${row.name} · ${row.kind}\n${status.venue} · ${status.localTime}'),isThreeLine:status!=null,trailing:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.end,children:[Text(_fmt(row.price)),Text(row.signal??'NEUTRE'),if(status!=null)Text(status.open?'OUVERT':'FERMÉ',style:TextStyle(fontWeight:FontWeight.bold,color:status.open?Colors.greenAccent:Colors.redAccent))])));})) ;}

class AssetDetailScreen extends StatefulWidget{const AssetDetailScreen({super.key,required this.row,required this.status,required this.historyRepo,required this.indicatorRepo,required this.ichimokuRepo});final MarketRow row;final MarketStatus? status;final HistoryRepository historyRepo;final IndicatorRepository indicatorRepo;final IchimokuHistoryRepository ichimokuRepo;@override State<AssetDetailScreen> createState()=>_AssetDetailState();}
class _AssetDetailState extends State<AssetDetailScreen>{String period='1d';static const periods=['15m','1h','4h','1d','1w','1mo','6mo','1y'];late Future<HistoryBundle> history;late Future<List<TimeframeComparison>> comparisons;late Future<IndicatorCenter> indicators;late Future<List<IchimokuSignalMarker>> markers;@override void initState(){super.initState();load();}void load(){history=widget.historyRepo.fetchHistory(symbol:widget.row.key,period:period);comparisons=widget.historyRepo.fetchComparisons(widget.row.key);indicators=widget.indicatorRepo.fetch(symbol:widget.row.key,period:period);markers=widget.ichimokuRepo.fetch(symbol:widget.row.key,period:period);}void changePeriod(String v)=>setState((){period=v;load();});
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.row.symbol)),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:ListTile(title:Text(widget.row.name),subtitle:Text(widget.status==null?widget.row.kind:'${widget.row.kind} · ${widget.status!.venue} · ${widget.status!.localTime}'),trailing:widget.status==null?null:Text(widget.status!.open?'OUVERT':'FERMÉ'))),const SizedBox(height:10),DropdownButtonFormField<String>(value:period,items:periods.map((p)=>DropdownMenuItem(value:p,child:Text(p))).toList(),onChanged:(v){if(v!=null)changePeriod(v);},decoration:const InputDecoration(labelText:'Période')),const SizedBox(height:16),FutureBuilder<HistoryBundle>(future:history,builder:(context,hs){if(hs.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(!hs.hasData)return Text('Historique indisponible : ${hs.error??'—'}');final data=hs.data!,a=data.analysis;return FutureBuilder<List<IchimokuSignalMarker>>(future:markers,builder:(context,sm){final list=sm.data??const<IchimokuSignalMarker>[];return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Graphique ${data.period}',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),Card(child:Padding(padding:const EdgeInsets.all(12),child:PriceSparkline(points:data.points,markers:list))),const SizedBox(height:8),Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Décision : ${a['decision']??'—'}'),Text('Confiance : ${a['confidence']??'—'}'),Text('RSI : ${a['rsi']??'—'}'),Text('Risque : ${a['risk']??'—'}')]))),if(list.isNotEmpty)...[const SizedBox(height:12),Text('Entrées / sorties Ichimoku historiques',style:Theme.of(context).textTheme.titleMedium),...list.reversed.take(8).map((m)=>Card(child:ListTile(leading:Icon(m.action=='ACHETER'?Icons.arrow_upward:Icons.arrow_downward,color:m.action=='ACHETER'?Colors.greenAccent:Colors.redAccent),title:Text('${m.action} · ${_fmt(m.price)}'),subtitle:Text(m.reason),trailing:Text('${m.confidence.toStringAsFixed(0)}%'))))]]);});}),const SizedBox(height:16),FutureBuilder<IndicatorCenter>(future:indicators,builder:(context,s){if(!s.hasData)return const SizedBox.shrink();final d=s.data!;return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Consensus technique',style:Theme.of(context).textTheme.titleLarge),Card(child:ListTile(title:Text(d.consensus),subtitle:Text('${d.symbol} · ${d.period}'))),...d.items.take(4).map((i)=>_IndicatorCard(name:i.name,value:'${i.value}\n${i.reading}',decision:i.decision,highlighted:i.name.contains('Ichimoku'),explanation:i.explanation))]);}),const SizedBox(height:16),FutureBuilder<List<TimeframeComparison>>(future:comparisons,builder:(context,s){if(!s.hasData)return const SizedBox.shrink();return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Multi-timeframes',style:Theme.of(context).textTheme.titleLarge),...s.data!.map((c)=>Card(child:ListTile(title:Text(c.period),subtitle:Text('RSI ${_fmt(c.rsi)} · Risque ${c.risk}'),trailing:Text('${c.decision}\n${c.confidence?.toStringAsFixed(0)??'—'}%',textAlign:TextAlign.right))))]);})]));}
}

class IndicatorsView extends StatefulWidget{const IndicatorsView({super.key,required this.rows,required this.repository});final List<MarketRow> rows;final IndicatorRepository repository;@override State<IndicatorsView> createState()=>_IndicatorsViewState();}
class _IndicatorsViewState extends State<IndicatorsView>{String? symbol;String period='1d';Future<IndicatorCenter>? center;static const periods=['15m','1h','4h','1d','1w','1mo','6mo','1y'];@override void didChangeDependencies(){super.didChangeDependencies();if(widget.rows.isNotEmpty&&symbol==null){symbol=widget.rows.first.key;center=widget.repository.fetch(symbol:symbol!,period:period);}}void load(){if(symbol==null)return;setState(()=>center=widget.repository.fetch(symbol:symbol!,period:period));}@override Widget build(BuildContext context){if(widget.rows.isEmpty)return const Center(child:Text('Aucun actif'));return ListView(padding:const EdgeInsets.all(16),children:[Text('Centre des indicateurs',style:Theme.of(context).textTheme.headlineSmall),Row(children:[Expanded(child:DropdownButtonFormField<String>(value:symbol,items:widget.rows.map((r)=>DropdownMenuItem(value:r.key,child:Text(r.symbol))).toList(),onChanged:(v){symbol=v;load();})),const SizedBox(width:8),SizedBox(width:110,child:DropdownButtonFormField<String>(value:period,items:periods.map((p)=>DropdownMenuItem(value:p,child:Text(p))).toList(),onChanged:(v){if(v!=null){period=v;load();}}))]),const SizedBox(height:12),FutureBuilder<IndicatorCenter>(future:center,builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(!s.hasData)return Text('${s.error??''}');final d=s.data!;return Column(children:[Card(child:ListTile(title:const Text('Consensus'),trailing:Text(d.consensus))),...d.items.map((i)=>_IndicatorCard(name:i.name,value:'${i.value}\n${i.reading}',decision:i.decision,highlighted:i.name.contains('Ichimoku'),explanation:i.explanation))]);})]);}}

class SignalsView extends StatelessWidget{const SignalsView({super.key,required this.rows});final List<MarketRow> rows;@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[Text('Signaux AI',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),...rows.where((r)=>r.signal!=null).map((r)=>_MarketTile(row:r))]);}

class NewsAlertsView extends StatefulWidget{const NewsAlertsView({super.key,required this.repository,required this.syncRepository,required this.rows});final NewsAlertRepository repository;final UserSyncRepository syncRepository;final List<MarketRow> rows;@override State<NewsAlertsView> createState()=>_NewsAlertsViewState();}
class _NewsAlertsViewState extends State<NewsAlertsView>{String severity='IMPORTANT';late Future<List<NewsAlertEvent>> events;late Future<UserSyncSnapshot> sync;Set<String> read={};@override void initState(){super.initState();load();}void load(){events=widget.repository.fetch(severity:severity);sync=widget.syncRepository.snapshot();}void change(String v)=>setState((){severity=v;events=widget.repository.fetch(severity:severity);});Future<void> markRead(String id)async{if(read.contains(id))return;try{await widget.syncRepository.markNotificationsRead([id]);if(mounted)setState(()=>read.add(id));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Lecture non synchronisée : $e')));}}@override Widget build(BuildContext context)=>FutureBuilder<UserSyncSnapshot>(future:sync,builder:(context,snapshot){if(snapshot.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(snapshot.hasData&&read.isEmpty)read=snapshot.data!.readNotificationIds.toSet();return ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('News & notifications',style:Theme.of(context).textTheme.headlineSmall)),DropdownButton<String>(value:severity,items:['INFO','IMPORTANT','CRITIQUE'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)change(v);})]),if(snapshot.hasError)Padding(padding:const EdgeInsets.only(top:8),child:Text('État lu/non-lu non synchronisé : ${snapshot.error}',style:TextStyle(color:Theme.of(context).colorScheme.error))),const SizedBox(height:12),FutureBuilder<List<NewsAlertEvent>>(future:events,builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(!s.hasData)return Text('News indisponibles : ${s.error??'—'}');final list=s.data!;if(list.isEmpty)return const Text('Aucune alerte pour ce filtre.');return Column(children:list.map((e)=>Card(child:ListTile(onTap:()=>markRead(e.id),leading:Icon(e.severity=='CRITIQUE'?Icons.warning_amber:e.severity=='IMPORTANT'?Icons.notifications_active_outlined:Icons.info_outline),title:Text('${e.severity} · ${e.assetKey}'),subtitle:Text('${e.title}\n${e.reason}'),isThreeLine:true,trailing:Icon(read.contains(e.id)?Icons.done_all:Icons.circle,size:read.contains(e.id)?20:8)))).toList());})]);});}

class _Metric extends StatelessWidget{const _Metric({required this.label,required this.value});final String label,value;@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label),Text(value,style:Theme.of(context).textTheme.headlineSmall)])));}
class _MarketTile extends StatelessWidget{const _MarketTile({required this.row});final MarketRow row;@override Widget build(BuildContext context)=>Card(child:ListTile(title:Text(row.symbol),subtitle:Text('${row.name} · ${row.kind}'),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.end,children:[Text(_fmt(row.price)),Text(row.signal??'NEUTRE')])));}
class _IndicatorCard extends StatelessWidget{const _IndicatorCard({required this.name,required this.value,required this.decision,this.highlighted=false,this.explanation=''});final String name,value,decision,explanation;final bool highlighted;@override Widget build(BuildContext context)=>Card(child:ListTile(leading:Icon(highlighted?Icons.auto_awesome:Icons.analytics_outlined),title:Text(name,style:highlighted?const TextStyle(fontWeight:FontWeight.bold):null),subtitle:Text(explanation.isEmpty?value:'$value\n$explanation'),isThreeLine:explanation.isNotEmpty,trailing:Text(decision)));}
String _fmt(num? value)=>value==null?'—':value.toDouble().toStringAsFixed(4);String _tone(String? signal){final s=(signal??'').toUpperCase();if(s.contains('ACH')||s.contains('BUY'))return'buy';if(s.contains('VEN')||s.contains('SELL'))return'sell';return'wait';}
